        proto.grant(op, 1)
    p = self.popen(argv, creationflags=0x00000004, **kw)  # Windows CREATE_SUSPENDED
    root = {"p": p, "identity": None, "evidence": argv_evidence(argv)}
    self.roots.append(root)
